def cc(n):
    s = ''
    while n != 0:
        s = str(n % 7) +  s
        n //= 7
    return s

def f(n):
    s = cc(n)
    if s[-1] == '2':
        s = s.replace('3','*').replace('1','3').replace('*','1')
        s = '21' + s
    else:
        s += '36'
        s = '1' + s[1:]
    return int(s,7)

